function earliestSecondToMarkIndices(nums, changeIndices) {
  const n = nums.length;
  const m = changeIndices.length;
  const total = nums.reduce((sum, value) => sum + value, 0) + n;
  const first = new Array(n + 1).fill(-1);
  for (let s = m - 1; s >= 0; s--) first[changeIndices[s]] = s;

  const pushMin = (heap, value) => {
    let child = heap.length;
    heap.push(value);
    while (child > 0 && heap[(child - 1) >> 1] > value) {
      heap[child] = heap[(child - 1) >> 1];
      child = (child - 1) >> 1;
    }
    heap[child] = value;
  };
  const popMin = (heap) => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    let parent = 0;
    let child = 1;
    while (child < heap.length) {
      if (child + 1 < heap.length && heap[child + 1] < heap[child]) child++;
      if (last <= heap[child]) break;
      heap[parent] = heap[child];
      parent = child;
      child = 2 * parent + 1;
    }
    heap[parent] = last;
    return top;
  };

  const canFinish = (seconds) => {
    const heap = [];
    let saved = 0;
    let free = 0;
    for (let s = seconds - 1; s >= 0; s--) {
      const index = changeIndices[s];
      const value = nums[index - 1];
      if (first[index] !== s || value <= 1) {
        free++;
        continue;
      }
      pushMin(heap, value);
      saved += value - 1;
      if (free > 0) {
        free--;
      } else {
        saved -= popMin(heap) - 1;
        free++;
      }
    }
    return total - saved <= seconds;
  };

  let low = n;
  let high = m + 1;
  while (low < high) {
    const mid = (low + high) >> 1;
    if (canFinish(mid)) high = mid;
    else low = mid + 1;
  }
  return low > m ? -1 : low;
}

brute:
function earliestSecondToMarkIndices(nums, changeIndices) {
  // Breadth-first over every reachable state: the current values plus a bitmask of marked indices.
  // Overwriting with 0 is the only useful overwrite, and a marked index keeps the value 0.
  const n = nums.length;
  const full = (1 << n) - 1;
  let states = new Map([[nums.join(',') + '|0', { values: nums.slice(), marked: 0 }]]);
  for (let s = 0; s < changeIndices.length; s++) {
    const next = new Map();
    const add = (values, marked) => next.set(values.join(',') + '|' + marked, { values, marked });
    for (const { values, marked } of states.values()) {
      add(values, marked);
      for (let i = 0; i < n; i++) {
        if (marked & (1 << i)) continue;
        if (values[i] > 0) add(values.map((v, j) => (j === i ? v - 1 : v)), marked);
        else if ((marked | (1 << i)) === full) return s + 1;
        else add(values, marked | (1 << i));
      }
      const target = changeIndices[s] - 1;
      if (!(marked & (1 << target))) add(values.map((v, j) => (j === target ? 0 : v)), marked);
    }
    states = next;
  }
  return -1;
}

generator:
function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(200, 600);
    const m = 2000;
    const changeIndices = Array.from({ length: m }, () => pick(1, n));
    const seen = new Set(changeIndices);
    const share = rand() * 0.4;
    const nums = Array.from({ length: n }, (_, i) => (seen.has(i + 1) && rand() < share ? pick(2, 1e9) : pick(0, 3)));
    return [nums, changeIndices];
  }
  const n = pick(1, 4);
  const m = pick(1, 10);
  const top = pick(0, 4);
  const nums = Array.from({ length: n }, () => pick(0, top));
  const changeIndices = Array.from({ length: m }, () => pick(1, n));
  return [nums, changeIndices];
}
